// SupplyAtSite is, per variant, what the site's supply orders still make of
// it (M107): the open ones and the drafts from a suggestion, quantity less
// produced, at least 0 — make-to-order orders left out.
func (q *Queries) SupplyAtSite(ctx context.Context, siteID int64) ([]SupplyAtSiteRow, error) {
	rows, err := q.db.Query(ctx, supplyAtSite, siteID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SupplyAtSiteRow
	for rows.Next() {
		var i SupplyAtSiteRow
		if err := rows.Scan(&i.VariantID, &i.Remaining); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertRule = `-- name: UpsertRule :exec
INSERT INTO manufacturing.replenishment_rules (variant_id, site_id, auto_create, auto_confirm, updated_by_user_id,
                                               updated_by_display, updated_at)
VALUES ($1, $2, $3, $4, $5, $6,
        $7::timestamptz)
ON CONFLICT (variant_id, site_id) DO UPDATE
SET auto_create = excluded.auto_create, auto_confirm = excluded.auto_confirm,
    updated_by_user_id = excluded.updated_by_user_id, updated_by_display = excluded.updated_by_display,
    updated_at = excluded.updated_at
`

type UpsertRuleParams struct {
	VariantID        int32
	SiteID           int64
	AutoCreate       bool
	AutoConfirm      bool
	UpdatedByUserID  *uuid.UUID
	UpdatedByDisplay *string
	Now              time.Time
}

func (q *Queries) UpsertRule(ctx context.Context, arg UpsertRuleParams) error {
	_, err := q.db.Exec(ctx, upsertRule,
		arg.VariantID,
		arg.SiteID,
		arg.AutoCreate,
		arg.AutoConfirm,
		arg.UpdatedByUserID,
		arg.UpdatedByDisplay,
		arg.Now,
	)
	return err
}
